/**
 * Story 12: image fixtures for unit / integration / e2e tests.
 *
 * The fixture files are generated by `scripts/generate-image-fixtures.mjs`
 * (no external image deps) and committed so test runs are reproducible.
 *
 * `fixtureBytes` reads from the generated base64 module (bytes.ts) so it
 * also works inside the workerd runtime, where node:fs cannot see the real
 * filesystem. `fixturePath` is for the Playwright project only.
 */
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { FIXTURES } from './bytes';

const dir = join(fileURLToPath(new URL('.', import.meta.url)));

/** Absolute path to a committed fixture file (Playwright only). */
export function fixturePath(name: string): string {
  return join(dir, name);
}

function base64ToBytes(b64: string): Uint8Array<ArrayBuffer> {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

/** Raw bytes of a committed fixture file (works in node and workerd). */
export function fixtureBytes(name: string): Uint8Array<ArrayBuffer> {
  const b64 = FIXTURES[name];
  if (!b64) throw new Error(`unknown image fixture: ${name}`);
  return base64ToBytes(b64);
}

/** JPEG magic bytes (prefix for sized JPEG buffers). */
export const JPEG_MAGIC: Uint8Array<ArrayBuffer> = new Uint8Array([
  0xff, 0xd8, 0xff, 0xe0, 0x00, 0x10, 0x4a, 0x46, 0x49, 0x46, 0x00, 0x01,
]);

/** PNG magic bytes (prefix for sized PNG buffers). */
export const PNG_MAGIC: Uint8Array<ArrayBuffer> = new Uint8Array([
  0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a,
]);

/** A buffer of exactly `size` bytes, starting with `magic`. */
export function sizedBytes(size: number, magic: Uint8Array<ArrayBuffer> = new Uint8Array(0)): Uint8Array<ArrayBuffer> {
  if (magic.length > size) throw new Error('magic longer than size');
  const out = new Uint8Array(size);
  out.set(magic);
  return out;
}
